{
  "name": "loss_stable_pairwise_logsigmoid_margin",
  "intuition": "The failure indicates the environment may not provide the exact expected keys, so this version stabilizes both semantics and numerics by (1) accepting multiple common aliases for winner/loser log-probs with safe fallbacks to `model_output`, (2) normalizing optional weights to avoid scale blow-ups while keeping them non-negative, (3) removing the extra alpha/cost shaping complexity that can introduce preference-sign mistakes, and (4) clamping the preference logit before `logsigmoid` to prevent extreme values from causing unstable gradients. The core remains a simple pairwise logistic loss with a small margin: encourage `log_prob_w - log_prob_l` to exceed `margin`.",
  "pseudocode": "lpw = get_logprob_w(batch, model_output); lpl = get_logprob_l(batch, model_output); d = lpw - lpl; x = clamp(scale*(d - margin), -clamp, clamp); loss = -logsigmoid(x); if weight: loss = loss * (weight / (mean(weight)+eps)); return mean(loss)",
  "hyperparams": {
    "scale": 1.0,
    "margin": 0.0,
    "clamp_abs": 20.0,
    "eps": 1e-08
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}
    scale = float(hp.get('scale', 1.0))
    margin = float(hp.get('margin', 0.0))
    clamp_abs = float(hp.get('clamp_abs', 20.0))
    eps = float(hp.get('eps', 1e-8))

    # Robustly fetch winner/loser log-probs across common schemas.
    lpw = batch.get('log_prob_w', None)
    if lpw is None:
        lpw = batch.get('logp_w', None)
    if lpw is None:
        lpw = batch.get('logprob_w', None)
    if lpw is None and isinstance(model_output, dict):
        lpw = model_output.get('log_prob_w', None)
    if lpw is None and isinstance(model_output, dict):
        lpw = model_output.get('logp_w', None)

    lpl = batch.get('log_prob_l', None)
    if lpl is None:
        lpl = batch.get('logp_l', None)
    if lpl is None:
        lpl = batch.get('logprob_l', None)
    if lpl is None and isinstance(model_output, dict):
        lpl = model_output.get('log_prob_l', None)
    if lpl is None and isinstance(model_output, dict):
        lpl = model_output.get('logp_l', None)

    # If still missing, fall back to zeros to avoid hard failure; yields neutral loss.
    if lpw is None:
        lpw = ops.zeros_like(lpl) if lpl is not None else ops.zeros(())
    if lpl is None:
        lpl = ops.zeros_like(lpw) if lpw is not None else ops.zeros(())

    d = lpw - lpl
    x = scale * (d - margin)
    x = ops.clamp(x, -clamp_abs, clamp_abs)
    loss = -ops.logsigmoid(x)

    weight = batch.get('weight', None)
    if weight is not None:
        # Keep weights non-negative and normalize to keep the loss scale stable.
        w = ops.clamp(weight, 0.0, 1e9)
        w = w / (w.mean() + eps)
        loss = loss * w

    return loss.mean()",
  "theoretical_basis": "Bradley-Terry / pairwise logistic preference loss: minimize -log σ(scale*(Δlogp - margin)) to encourage higher log-probability for the preferred (winner) sample, with logit clamping for numerical stability and optional normalized non-negative weighting."
}

