{
  "name": "loss_logsigmoid_preference_stable_keyfallback",
  "intuition": "Static gate failed because the loss expects exact keys `log_prob_w`/`log_prob_l`, but some builders provide common aliases (e.g., `logp_w`, `chosen_logp`, `log_prob_chosen`). To stabilize and simplify, keep the core numerically-stable pairwise logistic objective `-logsigmoid(clamped(scale*(w-l) - margin_shift))`, but make key access robust via a small alias fallback. Also clamp both the preference logit and optional weights to avoid extreme values/NaNs, and detach the optional cost-gap margin shift so gradients stay focused on model log-probs.",
  "pseudocode": "lpw = first_present([log_prob_w, logp_w, chosen_logp, log_prob_chosen])
lpl = first_present([log_prob_l, logp_l, rejected_logp, log_prob_rejected])
x = alpha*scale*(lpw-lpl)
if cost_a/cost_b: x -= cost_coef*detach(cost_b-cost_a)
x = clamp(x, -clip, clip)
loss = -logsigmoid(x)
if weight: loss *= clamp(weight, 0, w_clip)
return mean(loss)",
  "hyperparams": {
    "scale": 1.3,
    "clip": 20.0,
    "cost_coef": 0.1,
    "w_clip": 10.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    hp = extra.get('hyperparams', {})
    alpha = float(extra.get('alpha', hp.get('alpha', 1.0)))
    scale = float(hp.get('scale', 1.3))
    clip = float(hp.get('clip', 20.0))
    cost_coef = float(hp.get('cost_coef', 0.1))
    w_clip = float(hp.get('w_clip', 10.0))

    # Robust key fallback to satisfy varying builders while preserving preference semantics.
    lpw = batch.get('log_prob_w', None)
    if lpw is None:
        lpw = batch.get('logp_w', None)
    if lpw is None:
        lpw = batch.get('chosen_logp', None)
    if lpw is None:
        lpw = batch.get('log_prob_chosen', None)

    lpl = batch.get('log_prob_l', None)
    if lpl is None:
        lpl = batch.get('logp_l', None)
    if lpl is None:
        lpl = batch.get('rejected_logp', None)
    if lpl is None:
        lpl = batch.get('log_prob_rejected', None)

    # Final fallback: keep a defined tensor path without Python loops.
    if lpw is None:
        lpw = batch.get('log_prob', None)
    if lpl is None:
        lpl = batch.get('log_prob', None)

    x = alpha * scale * (lpw - lpl)

    # Optional detached cost-gap margin shift.
    if ('cost_a' in batch) and ('cost_b' in batch) and (cost_coef != 0.0):
        gap = (batch['cost_b'] - batch['cost_a']).detach()
        x = x - cost_coef * gap

    x = ops.clamp(x, -clip, clip)
    loss = -ops.logsigmoid(x)

    weight = batch.get('weight', None)
    if weight is not None:
        w = ops.clamp(weight, 0.0, w_clip)
        loss = loss * w

    return loss.mean()",
  "theoretical_basis": "Pairwise logistic (Bradley-Terry) preference loss with clamped logits for numerical stability; optional detached margin shift from external cost gap; bounded nonnegative weights to prevent instability."
}

