  "intuition": "The static gate failure indicates the environment expects canonical pairwise keys `log_prob_w` and `log_prob_l`. This simplifies to the most stable core: a clamped logistic (Bradley-Terry) loss on the log-prob difference. Clamping the margin prevents extreme values from causing numerical issues, and optional nonnegative weights are supported without changing preference semantics. I remove optional cost terms/conditionals to avoid missing-key paths and keep the loss strictly aligned with the expected schema.",
  "pseudocode": "d = log_prob_w - log_prob_l
x = clamp(alpha * scale * d, -clamp_val, clamp_val)
loss = -logsigmoid(x)
if weight: loss *= clamp(weight, 0, inf)
return mean(loss)",
  "hyperparams": {
    "scale": 1.0,
    "clamp_val": 20.0
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    lpw = batch['log_prob_w']
    lpl = batch['log_prob_l']
    weight = batch.get('weight', None)

    hp = extra.get('hyperparams', {}) if isinstance(extra, dict) else {}
    alpha = float(extra.get('alpha', hp.get('alpha', 1.0))) if isinstance(extra, dict) else 1.0
    scale = float(hp.get('scale', 1.0))
    clamp_val = float(hp.get('clamp_val', 20.0))

    d = lpw - lpl
    x = ops.clamp(alpha * scale * d, -clamp_val, clamp_val)
    loss = -ops.logsigmoid(x)

    if weight is not None:
        loss = loss * ops.clamp(weight, 0.0, float('inf'))

    return loss.mean()",
  "theoretical_basis": "Stable pairwise logistic preference loss (Bradley-Terry) on log-prob differences; clamped margin for numerical stability; optional nonnegative weighting preserves preference semantics."
}

