  "pseudocode": "lpw=batch[log_prob_w]; lpl=batch[log_prob_l]; gap=(cost_b-cost_a).detach(); x=alpha*scale*(lpw-lpl)-beta*gap; x=clamp(x, clamp_min, clamp_max); loss=-logsigmoid(x); if weight: loss*=clamp(weight,0,inf)/(mean(clamp(weight,0,inf))+eps); return mean(loss)",
