  "code": "def generated_loss(batch, model_output, extra):
    hp = extra.get('hyperparams', {}) if extra is not None else {}
    alpha = float(extra.get('alpha', hp.get('alpha', 1.0))) if extra is not None else float(hp.get('alpha', 1.0))
    scale = float(hp.get('scale', 1.15))
    beta = float(hp.get('beta', 0.2))
    clamp_min = float(hp.get('clamp_min', -15.0))
    clamp_max = float(hp.get('clamp_max', 15.0))
    eps = float(hp.get('eps', 1e-6))

    # Prefer canonical keys; fall back to common aliases in batch/model_output.
    lpw = batch.get('log_prob_w', batch.get('logprob_w', batch.get('chosen_logprob', batch.get('logp_w', None))))
    lpl = batch.get('log_prob_l', batch.get('logprob_l', batch.get('rejected_logprob', batch.get('logp_l', None))))
    if lpw is None and isinstance(model_output, dict):
        lpw = model_output.get('log_prob_w', model_output.get('logprob_w', model_output.get('chosen_logprob', model_output.get('logp_w', None))))
    if lpl is None and isinstance(model_output, dict):
        lpl = model_output.get('log_prob_l', model_output.get('logprob_l', model_output.get('rejected_logprob', model_output.get('logp_l', None))))

    cost_a = batch.get('cost_a', None)
    cost_b = batch.get('cost_b', None)
    if cost_a is None and isinstance(model_output, dict):
        cost_a = model_output.get('cost_a', None)
    if cost_b is None and isinstance(model_output, dict):
        cost_b = model_output.get('cost_b', None)

    # Fallback tensors if log-probs are missing; keep shapes compatible.
    if lpw is None:
        ref = cost_a if cost_a is not None else cost_b
        if ref is None:
            if isinstance(model_output, dict):
                ref = model_output.get('cost_a', model_output.get('cost_b', None))
        lpw = ops.zeros_like(ref)
    if lpl is None:
        lpl = ops.zeros_like(lpw)

    if cost_a is None or cost_b is None:
        gap = ops.zeros_like(lpw)
    else:
        gap = (cost_b - cost_a).detach()

    x = alpha * scale * (lpw - lpl) - beta * gap
    x = ops.clamp(x, clamp_min, clamp_max)
    loss = -ops.logsigmoid(x)

    weight = batch.get('weight', None)
    if weight is not None:
        w = ops.clamp(weight, 0.0, 1e9)
        w = w / (w.mean() + eps)
        loss = loss * w

    return loss.mean()",
  "theoretical_basis": ""
}

